      window.setEndDate = function () {
        var initiatorId = functions.getValues().Initiator;
        var vacationTypeId = functions.getValues().VacationType;
        var vacationReasonId = functions.getValues().VacationReason;
        var beginDate = functions.getValues().BeginDate;
        var duration = functions.getValues().Duration;
        if (duration != null && beginDate != null) {
          var url = `/api/functions/NNGetVacationEndDate?dateBegin=${beginDate}&duration=${duration}&userId=${initiatorId}&vacationTypeId=${vacationTypeId}&vacationReasonId=${vacationReasonId}`
          ESS.network.sendRequest(url)
          .then(function (newEndDateValue) {
            functions.setValue('EndDate', newEndDateValue);
          });
        }
      }
	  
	  // Функция обновления полей уточнения причины отпуска
      window.updateClarificationFields = function(selectedReasonId, isActualTop) {
        console.log('=== updateClarificationFields СТАРТ ===');
        console.log('1. selectedReasonId =', selectedReasonId);
		
        var isTop = isActualTop != null ? isActualTop : (functions.getValues().IsTop || false);
        console.log('2. isTop =', isTop);
        
        // Если причина не выбрана - скрываем поля
        if (!selectedReasonId) {
          console.log('3. Причина НЕ выбрана - скрываем поля');
          functions.setIsItemHidden('VacationСlarificationReasonRequired', true);
          functions.setIsItemHidden('VacationСlarificationReasonOptional', true);
          functions.setValue('VacationСlarificationReasonRequired', '');
          functions.setValue('VacationСlarificationReasonOptional', '');
          console.log('=== updateClarificationFields КОНЕЦ (причина не выбрана) ===');
          return;
        }
        
        console.log('4. Отправка запроса: /api/functions/GetVacationReasonsWithClarificationIds');
        
        // Получаем список ID причин, требующих уточнения
        ESS.network.sendRequest(`/api/functions/GetVacationReasonsWithClarificationIds`)
        .then(function (vacationReasonsIdsString) {
          console.log('5. Ответ от API =', vacationReasonsIdsString);
          console.log('6. Тип данных:', typeof vacationReasonsIdsString);
          
          // Проверка на пустую строку или null/undefined
          if (!vacationReasonsIdsString || vacationReasonsIdsString.trim() === '') {
            console.log('7. ОШИБКА: Получена пустая строка или null от API');
            ESS.toasts.showToast(ESS.L('@HRPROVACATIONS.FACILITIES_GETVACATION_CONSENT_ERROR'), 'danger', true);
            functions.setIsItemHidden('VacationСlarificationReasonRequired', true);
            functions.setIsItemHidden('VacationСlarificationReasonOptional', true);
            console.log('=== updateClarificationFields КОНЕЦ (пустой ответ API) ===');
            return;
          }
          
          // Парсим строку с ID (например: "15,23,47,52")
          var clarificationRequiredIds = vacationReasonsIdsString.split(',').map(function(id) {
            return parseInt(id.trim(), 10);
          });
          
          console.log('8. Распарсенный массив =', clarificationRequiredIds);
          console.log('9. selectedReasonId (число) =', parseInt(selectedReasonId, 10));
          
          // Проверяем, требует ли выбранная причина уточнения
          var requiresClarification = clarificationRequiredIds.includes(parseInt(selectedReasonId, 10));
          
          console.log('10. requiresClarification =', requiresClarification);
          
          if (requiresClarification) {
			console.log('11. Причина ТРЕБУЕТ уточнения');
			
				// ПОКАЗЫВАЕМ нужное поле в зависимости от isTop
				if (isTop) {
					console.log('12. isTop = true -> показываем необязательное поле');
					functions.setIsItemHidden('VacationСlarificationReasonOptional', false);
					functions.setIsItemHidden('VacationСlarificationReasonRequired', true);
				} else {
					console.log('13. isTop = false -> показываем обязательное поле');
					functions.setIsItemHidden('VacationСlarificationReasonRequired', false);
					functions.setIsItemHidden('VacationСlarificationReasonOptional', true);
				}
			} else {
				console.log('14. Причина НЕ ТРЕБУЕТ уточнения - скрываем оба поля');
				functions.setIsItemHidden('VacationСlarificationReasonRequired', true);
				functions.setIsItemHidden('VacationСlarificationReasonOptional', true);
				functions.setValue('VacationСlarificationReasonRequired', '');
				functions.setValue('VacationСlarificationReasonOptional', '');
			}

          console.log('=== updateClarificationFields КОНЕЦ (успешно) ===');
        })
        .catch(function (error) {
          console.error('16. ОШИБКА в updateClarificationFields:', error);
          ESS.toasts.showToast(ESS.L('@HRPROVACATIONS.FACILITIES_GETVACATION_CONSENT_ERROR'), 'danger', true);
          functions.setIsItemHidden('VacationСlarificationReasonRequired', true);
          functions.setIsItemHidden('VacationСlarificationReasonOptional', true);
          console.log('=== updateClarificationFields КОНЕЦ (ошибка) ===');
        });
      };
      
      window.getSubstitutionDataFromStorage = function() {
        try {
          var storedData = localStorage.getItem('NNSubstitutionSetup_Data');
          
          if (!storedData || storedData === '' || storedData === 'null') {
            console.log('[getSubstitutionDataFromStorage] No data in localStorage');
            return null;
          }
          
          var data = JSON.parse(storedData);
          
          if (!data.SubstituteIdsString || data.SubstituteIdsString === '') {
            console.log('[getSubstitutionDataFromStorage] No substitute IDs');
            return null;
          }
          
          var result = {
            substituteIds: data.SubstituteIdsString.split(';').filter(function(id) { return id && id !== ''; }),
            substituteNames: data.SubstituteNamesString ? data.SubstituteNamesString.split(';') : [],
            systemIds: data.SystemIdsString.split(';').filter(function(id) { return id && id !== ''; }),
            systemNames: data.SystemNamesString ? data.SystemNamesString.split(';') : [],
            startDates: data.StartDatesString.split(';').filter(function(date) { return date && date !== ''; }),
            endDates: data.EndDatesString.split(';').filter(function(date) { return date && date !== ''; })
          };
          
          console.log('[getSubstitutionDataFromStorage] Data loaded:', result.substituteIds.length, 'substitutes');
          return result;
        }
        catch (e) {
          console.error('[getSubstitutionDataFromStorage] Parse error:', e);
          return null;
        }
      };

      window.showSubstitutionInfo = function() {
        var data = window.getSubstitutionDataFromStorage();
        
        if (!data || data.substituteIds.length === 0) {
          console.log('[showSubstitutionInfo] No data to display');
          functions.setIsItemHidden('SubstitutionsInfoBlock', true);
          functions.setIsItemHidden('ShowSubstitutesButton', true);
          functions.setValue('SubstitutionsInfo', '');
          return false;
        }
        
        var infoText = ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_HEADER')) + '<br/><br/>';
        
        for (var i = 0; i < data.substituteIds.length; i++) {
          var startDate = data.startDates[i] ? new Date(data.startDates[i]).toLocaleDateString('ru-RU') : '?';
          var endDate = data.endDates[i] ? new Date(data.endDates[i]).toLocaleDateString('ru-RU') : '?';
          var subName = data.substituteNames[i];
          var sysName = data.systemNames[i];
          
          infoText += ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_ITEM_TEMPLATE'),(i + 1), subName, sysName , startDate, endDate) + '<br/>';
        }
        
        functions.setValue('SubstitutionsInfo', infoText);
        functions.setIsItemHidden('SubstitutionsInfoBlock', false);
        functions.setIsItemHidden('ShowSubstitutesButton', false);
        
        console.log('[showSubstitutionInfo] Info displayed');
        return true;
      };

      window.prepareSubstitutionParameters = function() {
        var data = window.getSubstitutionDataFromStorage();
        
        if (!data || data.substituteIds.length === 0) {
          console.log('[prepareSubstitutionParameters] No data to prepare');
          
          functions.setValue('SubstituteIdsString', '');
          functions.setValue('SystemIdsString', '');
          functions.setValue('StartDatesString', '');
          functions.setValue('EndDatesString', '');
          functions.setValue('SubstitutionsInfo', '');
          return false;
        }
		
        var infoText = ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_HEADER')) + '<br/><br/>';
        
        for (var i = 0; i < data.substituteIds.length; i++) {
          var startDate = data.startDates[i] ? new Date(data.startDates[i]).toLocaleDateString('ru-RU') : '?';
          var endDate = data.endDates[i] ? new Date(data.endDates[i]).toLocaleDateString('ru-RU') : '?';
          var subName = data.substituteNames[i];
          var sysName = data.systemNames[i];
          
          infoText += ESS.formatString(ESS.L('@HRPROVACATIONS.SUBSTITUTION_INFO_ITEM_TEMPLATE'),(i + 1), subName, sysName , startDate, endDate) + '<br/>';
        }
        
        functions.setValue('SubstitutionsInfo', infoText);
        functions.setValue('SubstituteIdsString', data.substituteIds.join(';'));
        functions.setValue('SystemIdsString', data.systemIds.join(';'));
        functions.setValue('StartDatesString', data.startDates.join(';'));
        functions.setValue('EndDatesString', data.endDates.join(';'));
        
        console.log('[prepareSubstitutionParameters] Parameters set:', data.substituteIds.length, 'substitutes');
        return true;
      };
      
      window.toIsoDateString = function (value) {
        var d = new Date(value);
        if (isNaN(d.getTime())) {
          return null;
        }
        var year = d.getFullYear(); 
        var month = String(d.getMonth() + 1).padStart(2, '0'); 
        var day = String(d.getDate()).padStart(2, '0');  
        var result = year + "-" + month + "-" + day;
  
        return result;
      }
      
      console.log('openedEventHandler. Конец события. ИД текущего инициатора = ' + functions.getValues().Initiator);

facility.beforeSubmitEventHandler:
    window.prepareSubstitutionParameters();

    var initiatorId = functions.getValues().Initiator;
    var vacationType = functions.getValues().VacationType;
    var vacationReason = functions.getValues().VacationReason;
    var beginDate = functions.getValues().BeginDate;
    var endDate = functions.getValues().EndDate;
    var duration = functions.getValues().Duration;
    functions.setValue('Field_Продолжительность_отпуска', duration);

    var getVacationTypeName = ESS.network.sendRequest(`/api/functions/GetVacationTypeName?vacationTypeId=${vacationType}`)
    .then(function (typeName) {
      functions.setValue('Field_Вид_отпуска', typeName);
    });

    var getVacationReasonName = ESS.network.sendRequest(`/api/functions/GetVacationReasonName?id=${vacationReason}`)
    .then(function (reasonName) {
      functions.setValue('Field_Причина_отпуска', reasonName);
    });

    // Сохраняем значение уточнения в поле для документа
    var clarificationReason = functions.getValues().VacationСlarificationReasonRequired || 
                              functions.getValues().VacationСlarificationReasonOptional || '';
    functions.setValue('Field_Уточнение_причины_отпуска', clarificationReason);
	var reasonFieldValue = functions.getValues().Field_Уточнение_причины_отпуска;
	console.log('Field_Уточнение_причины_отпуска = ', reasonFieldValue);

    var beginDateLocale = JSON.stringify(window.toIsoDateString(functions.getValues().BeginDate));
    var endDateLocale = JSON.stringify(window.toIsoDateString(functions.getValues().EndDate));
    var dates = [];
    dates.push(beginDateLocale);
    dates.push(endDateLocale);
    var getFormatDates = ESS.network.sendRequest(`/api/functions/GetFormatDates?employeeId=${initiatorId}&dates=[${dates}]`)
    .then(function (dates) {
      functions.setValue('Field_Дата_начала_отпуска', dates[0]);
      functions.setValue('Field_Дата_окончания_отпуска', dates[1]);
    });

    var validateVacationData = ESS.scripts.HRProVacations.validateOtherVacationData({ functions, initiatorId, statementId: 0, vacationType, vacationReason, beginDate, endDate, duration });

    var validateSubstitutionDates = function() {
      var substitutionsInfo = functions.getValues().SubstitutionsInfo;
      
      if (!substitutionsInfo || substitutionsInfo === '' || substitutionsInfo === 'null') {
        return Promise.resolve({ isValid: true, errors: [] });
      }
      
      var vacationPeriodsJson = '';
      if (beginDate && endDate) {
        var periods = [{ StartDate: beginDate, EndDate: endDate }];
        vacationPeriodsJson = JSON.stringify(periods);
      }
      
      return ESS.scripts.HRProVacations.validateSubstitutionDates({ VacationPeriodsJson: vacationPeriodsJson, StartDatesString: functions.getValues().StartDatesString || '', EndDatesString: functions.getValues().EndDatesString || '', IsCallingService: true });
    };

    Promise.all([getVacationTypeName, getVacationReasonName, getFormatDates, validateVacationData, validateSubstitutionDates()])
    .then(function(results) {
      var substitutionResult = results[4];
      if (substitutionResult && !substitutionResult.isValid) {
        if (substitutionResult.errors && substitutionResult.errors.length > 0) {
        ESS.toasts.showToast(substitutionResult.errors[0].message, 'danger', true);
      }
        reject();
        return;
      }
      resolve();
    })
    .catch(function(error) {
      reject();
    });
